    """
    Return the length of the longest common subsequence of two strings.
    If either argument is not a string, returns None.
    """
    # Input validation
    if not isinstance(text1, str) or not isinstance(text2, str):
        return None

    # Empty strings -> LCS length 0
    if not text1 or not text2:
        return 0

    # Work with the shorter string in the inner loop to save memory
    if len(text1) < len(text2):
        short, long_ = text1, text2
    else:
        short, long_ = text2, text1

    short_len = len(short)
    # DP rows: previous and current
