class LRUCache:
    def __init__(self, capacity: int):
        # Treat negative capacities as zero (no storage possible)
        self.capacity = max(0, capacity)
        self.cache: OrderedDict[int, int] = OrderedDict()

    def get(self, key: int) -> int:
        """Return value associated with key, or -1 if not present."""
        if key not in self.cache:
            return -1
        # Move accessed key to the front (most recently used)
        self.cache.move_to_end(key, last=False)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        """Insert or update the key with value, evict LRU if needed."""
        if self.capacity == 0:
            return  # Nothing can be stored

        if key in self.cache:
            # Update value and mark as most recent
            self.cache[key] = value
            self.cache.move_to_end(key, last=False)
        else:
            # Insert new key as most recent
            self.cache[key] = value
            self.cache.move_to_end(key, last=False)
            # Evict least recently used if over capacity
            if len(self.cache) > self.capacity:
                # popitem(last=True) removes the last (LRU) item
                self.cache.popitem(last=True)

